algorithm CheckPalindrome
    define word as string;
    define i as integer;
    define wordLength as integer;
    define isPalindrome as integer;
    read word;
    wordLength <- length(word);
    isPalindrome <- 1;
    for i <- 0 to wordLength div 2 - 1 step 1 do
        if charAt(word, i) <> charAt(word, wordLength - 1 - i) then
            isPalindrome <- 0;
        endIf
    endFor
    write isPalindrome;
endAlgorithm
